    def build(n, mode, valf):
        L = [-1] * n
        R = [-1] * n
        val = [valf() for _ in range(n)]
        if mode == 'random':
            free = [0]
            for i in range(1, n):
                k = rng.randrange(len(free))
                p = free[k]
                if L[p] == -1 and R[p] == -1:
                    side = rng.randint(0, 1)
                elif L[p] == -1:
                    side = 0
                else:
                    side = 1
                if side == 0:
                    L[p] = i
                else:
                    R[p] = i
                if L[p] != -1 and R[p] != -1:
                    free[k] = free[-1]
                    free.pop()
                free.append(i)
        elif mode == 'chain':
            for i in range(1, n):
                if rng.random() < 0.5:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
        elif mode == 'complete':
            for i in range(1, n):
                p = (i - 1) // 2
                if i % 2 == 1:
                    L[p] = i
                else:
                    R[p] = i
        return L, R, val

    def ser(L, R, val):
        out = []
        q = [0]
        h = 0
        while h < len(q):
            x = q[h]
            h += 1
            if x == -1:
                out.append('null')
                continue
            out.append(str(val[x]))
            q.append(L[x])
            q.append(R[x])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def tree(n, mode, valf):
        return ser(*build(n, mode, valf))

