    tests.append(tree(10**5, 'complete', lambda: rng.randint(-10**9, 10**9)))
    tests.append(tree(10**5, 'random', lambda: rng.randint(1, 100)))
    tests.append(tree(99999, 'complete', lambda: 0))
    tests.append(tree(10**5, 'random', lambda: 5))
    return tests

